import{_ as s,C as o,c as i,o as c,a3 as n,G as a,j as r,a as l}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Manage currency","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/companies/currency.md","filePath":"master/general-settings/companies/currency.md","lastUpdated":1791902625000}'),u={name:"master/general-settings/companies/currency.md"};function g(m,e,h,d,y,p){const t=o("ImagePopup");return c(),i("div",null,[e[0]||(e[0]=n('<h1 id="manage-currency" tabindex="-1">Manage currency <a class="header-anchor" href="#manage-currency" aria-label="Permalink to &quot;Manage currency&quot;">​</a></h1><p>The <strong>Manage Currency</strong> page sets the <strong>Base Currency</strong> of your system. Product prices are stored in this currency. They are converted to the company currency when you make a sale or purchase.</p><blockquote><p><strong>In simple words:</strong> The base currency is the one your product prices are kept in.</p></blockquote><h2 id="set-the-base-currency" tabindex="-1">Set the base currency <a class="header-anchor" href="#set-the-base-currency" aria-label="Permalink to &quot;Set the base currency&quot;">​</a></h2><ol><li>Go to <code>Settings → Settings</code>.</li><li>In the left menu, under <strong>General</strong>, click <strong>Manage Currency</strong>.</li><li>In <strong>Base Currency</strong>, choose a currency. Type to search the list.</li><li>Click <strong>Save changes</strong>.</li></ol>',5)),a(t,{src:"/images1/general-settings/manage_currency_page.png",alt:"Manage Currency page with the Base Currency field"}),e[1]||(e[1]=n('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>The list shows only active currencies. If yours is missing, activate it first. See <a href="#manage-currencies">Manage currencies</a>.</p></div><h2 id="manage-currencies" tabindex="-1">Manage currencies <a class="header-anchor" href="#manage-currencies" aria-label="Permalink to &quot;Manage currencies&quot;">​</a></h2><p>The currency list is not in the Settings menu. It appears in the Configuration menu of modules that use money, for example Invoices, Sales, Purchases and Accounting. The menu item is <strong>Currencies</strong>.</p><ol><li>Open the Configuration menu of one of these modules.</li><li>Click <strong>Currencies</strong>.</li></ol>',4)),a(t,{src:"/images1/general-settings/currencies_list.png",alt:"Currencies list with the Status toggle column"}),e[2]||(e[2]=n('<h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The list shows these columns:</p><ul><li><strong>Currency Name</strong>, <strong>Symbol</strong>, <strong>Full Name</strong>, <strong>ISO Code</strong>, <strong>Decimal Places</strong>, <strong>Rounding</strong>.</li><li><strong>Status:</strong> A toggle that shows if the currency is active.</li><li><strong>Created At</strong> and <strong>Updated At:</strong> Hidden by default. Use the column menu to show them.</li></ul><p>Active currencies are listed first. You can search, sort, group by <strong>Name</strong>, <strong>Status</strong> or <strong>Decimal Places</strong>, and filter by <strong>Status</strong>.</p><h3 id="create-or-edit-a-currency" tabindex="-1">Create or edit a currency <a class="header-anchor" href="#create-or-edit-a-currency" aria-label="Permalink to &quot;Create or edit a currency&quot;">​</a></h3><ol><li>Click the create button, or open a row and click <strong>Edit</strong>.</li><li>Fill in <strong>Currency Information</strong>: <ul><li><strong><em>Currency Name:</em></strong> The official name. Required.</li><li><strong><em>Currency Symbol:</em></strong> The sign, for example <code>$</code>.</li><li><strong><em>Full Name:</em></strong> The long name.</li><li><strong><em>ISO Numeric Code:</em></strong> A number from 1 to 999.</li></ul></li><li>Fill in <strong>Format Configuration</strong>: <ul><li><strong><em>Decimal Places:</em></strong> From 0 to 6. The default is 2.</li><li><strong><em>Rounding Precision:</em></strong> The rounding used in calculations.</li></ul></li><li>In <strong>Status &amp; Configuration</strong>, use <strong><em>Status</em></strong> to turn the currency on or off. It is on by default.</li><li>Save the record.</li></ol>',6)),a(t,{src:"/images1/general-settings/currency_form.png",alt:"New currency form with currency, format and status sections"}),e[3]||(e[3]=n('<h3 id="enable-or-archive-a-currency" tabindex="-1">Enable or archive a currency <a class="header-anchor" href="#enable-or-archive-a-currency" aria-label="Permalink to &quot;Enable or archive a currency&quot;">​</a></h3><p>Use the <strong>Status</strong> toggle in the list, or on the form. Off means the currency is archived and cannot be chosen.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A currency used by a company cannot be deactivated. You see <strong>Currency cannot be deactivated</strong>. A currency in use also cannot be deleted.</p></div><h3 id="set-currency-rates" tabindex="-1">Set currency rates <a class="header-anchor" href="#set-currency-rates" aria-label="Permalink to &quot;Set currency rates&quot;">​</a></h3><p>The <strong>Currency Rates</strong> section keeps past exchange rates against the base currency.</p><ol><li>Open the currency and click <strong>Edit</strong>.</li><li>In <strong>Currency Rates</strong>, click <strong>Add Rate</strong>.</li><li>Fill in the row: <ul><li><strong><em>Date:</em></strong> The day the rate starts. Today by default.</li><li><strong><em>Unit Per [base currency]:</em></strong> The rate. The minimum is 1.</li><li><strong><em>[Base currency] Per Unit:</em></strong> Filled in for you. It is the inverse of the rate.</li></ul></li><li>Save the record.</li></ol><p>You need at least one rate row. Use the clone icon to copy a row. Deleting a row asks you to confirm.</p>',7)),a(t,{src:"/images1/general-settings/currency_rates.png",alt:"Currency Rates section with the Add Rate button and one rate row"}),e[4]||(e[4]=r("h2",{id:"see-also",tabindex:"-1"},[l("See also "),r("a",{class:"header-anchor",href:"#see-also","aria-label":'Permalink to "See also"'},"​")],-1)),e[5]||(e[5]=r("ul",null,[r("li",null,[r("a",{href:"./companies.html"},"Companies")]),r("li",null,[r("a",{href:"./../"},"General settings overview")])],-1))])}const b=s(u,[["render",g]]);export{_ as __pageData,b as default};
